165	export class InfiniteGalleryRenderer {
166	  private _renderer: THREE.WebGLRenderer | null = null;
167	  private _scene: THREE.Scene | null = null;
168	  private _camera: THREE.PerspectiveCamera | null = null;
169	  private _clock: THREE.Clock | null = null;
170	  private _raycaster: THREE.Raycaster | null = null;
171	  private _canvas: HTMLCanvasElement | null = null;
172	
173	  private _planes: PlaneRecord[] = [];
174	  private _meshList: THREE.Object3D[] = [];
175	  private _textures: (THREE.Texture | null)[] = [];
176	  private _geometries: THREE.BufferGeometry[] = [];
177	  private _materials: THREE.ShaderMaterial[] = [];
178	
179	  private _rafId: number | null = null;
180	  private _rendering = false;
181	  private _disposed = false;
182	
183	  private _resizeObserver: ResizeObserver | null = null;
184	  private _intersectionObserver: IntersectionObserver | null = null;
185	
186	  private _scrollVelocity = 0;
187	  private _lastInteractionMs = 0;
188	  private _isAutoPlaying = false;
189	  private _autoPlayIntervalId: ReturnType<typeof setInterval> | null = null;
190	  private _hoveredIndex = -1;
191	  private _touchLastY = 0;
192	
193	  private readonly _pointerNDC = new THREE.Vector2();
194	
195	  private readonly _onWheel: (e: WheelEvent) => void;
196	  private readonly _onKeyDown: (e: KeyboardEvent) => void;
197	  private readonly _onTouchStart: (e: TouchEvent) => void;
198	  private readonly _onTouchMove: (e: TouchEvent) => void;
199	  private readonly _onPointerMove: (e: PointerEvent) => void;
200	  private readonly _onPointerLeave: (e: PointerEvent) => void;
201	
202	  constructor() {
203	    this._onWheel = (e) => {
204	      e.preventDefault();
205	      this._recordInteraction();
206	      this._scrollVelocity += e.deltaY * 0.01 * SCROLL_SPEED;
207	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
208	    };
209	    this._onKeyDown = (e) => {
210	      if (e.key === "ArrowDown" || e.key === "ArrowRight") {
211	        this._recordInteraction();
212	        this._scrollVelocity += 2 * SCROLL_SPEED;
213	      } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
214	        this._recordInteraction();
215	        this._scrollVelocity -= 2 * SCROLL_SPEED;
216	      }
217	    };
218	    this._onTouchStart = (e) => {
219	      if (e.touches[0]) this._touchLastY = e.touches[0].clientY;
220	      this._recordInteraction();
221	    };
222	    this._onTouchMove = (e) => {
223	      e.preventDefault();
224	      if (!e.touches[0]) return;
225	      const y = e.touches[0].clientY;
226	      const delta = this._touchLastY - y;
227	      this._touchLastY = y;
228	      this._recordInteraction();
229	      this._scrollVelocity += delta * 0.03 * SCROLL_SPEED;
230	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
231	    };
232	    this._onPointerMove = (e) => {
233	      const canvas = this._canvas;
234	      const camera = this._camera;
235	      const raycaster = this._raycaster;
236	      if (!canvas || !camera || !raycaster) return;
237	      const rect = canvas.getBoundingClientRect();
238	      this._pointerNDC.set(
239	        ((e.clientX - rect.left) / rect.width) * 2 - 1,
240	        -((e.clientY - rect.top) / rect.height) * 2 + 1,
241	      );
242	      raycaster.setFromCamera(this._pointerNDC, camera);
243	      const intersects = raycaster.intersectObjects(this._meshList, false);
244	      if (intersects.length > 0) {
245	        const hit = intersects[0]?.object;
246	        this._hoveredIndex = this._planes.findIndex((r) => r.mesh === hit);
247	      } else {
248	        this._hoveredIndex = -1;
249	      }
250	    };
251	    this._onPointerLeave = (_e) => {
252	      this._hoveredIndex = -1;
253	    };
254	  }
255	
256	  async init(canvas: HTMLCanvasElement): Promise<void> {
257	    this._canvas = canvas;
258	
259	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
260	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
261	    renderer.setClearAlpha(0);
262	    this._renderer = renderer;
263	
264	    const scene = new THREE.Scene();
265	    this._scene = scene;
266	
267	    const w = Math.max(canvas.clientWidth, 1);
268	    const h = Math.max(canvas.clientHeight, 1);
269	    const camera = new THREE.PerspectiveCamera(55, w / h, 0.1, 200);
270	    camera.position.set(0, 0, 0);
271	    this._camera = camera;
272	
273	    this._clock = new THREE.Clock();
274	    this._raycaster = new THREE.Raycaster();
275	
276	    const loader = new THREE.TextureLoader();
277	    const textures = await Promise.all(
278	      GALLERY_IMAGES.map((url) => loadTexture(loader, url)),
279	    );
280	    if (this._disposed) return;
281	
282	    this._textures = textures;
283	    this._buildPlanes(textures);
284	    this._syncSize();
285	    this._observeResize();
286	    this._observeVisibility();
287	    this._attachInputListeners();
288	
289	    this._autoPlayIntervalId = setInterval(() => this._tickAutoPlay(), 100);
290	  }
291	
292	  dispose(): void {
293	    this._disposed = true;
294	    this._stopRaf();
295	
296	    if (this._autoPlayIntervalId !== null) {
297	      clearInterval(this._autoPlayIntervalId);
298	      this._autoPlayIntervalId = null;
299	    }
300	
301	    if (this._canvas) this._detachInputListeners();
302	
303	    this._resizeObserver?.disconnect();
304	    this._resizeObserver = null;
305	    this._intersectionObserver?.disconnect();
306	    this._intersectionObserver = null;
307	
308	    this._geometries.forEach((g) => g.dispose());
309	    this._geometries = [];
310	    this._materials.forEach((m) => m.dispose());
311	    this._materials = [];
312	    this._textures.forEach((t) => t?.dispose());
313	    this._textures = [];
314	
315	    this._renderer?.dispose();
316	    this._renderer?.forceContextLoss();
317	    this._renderer = null;
318	    this._scene = null;
319	    this._camera = null;
320	    this._clock = null;
321	    this._raycaster = null;
322	    this._canvas = null;
323	    this._planes = [];
324	    this._meshList = [];
325	  }
326	
327	  private _buildPlanes(textures: (THREE.Texture | null)[]): void {
328	    const count = GALLERY_IMAGES.length;
329	    const scene = this._scene!;
330	
331	    for (let i = 0; i < VISIBLE_COUNT; i++) {
332	      // Spatial spread matching the original golden-angle distribution
333	      const hAngle = (i * 2.618) % (Math.PI * 2);
334	      const vAngle = (i * 1.618 + Math.PI / 3) % (Math.PI * 2);
335	      const hRadius = (i % 3) * 1.2;
336	      const vRadius = ((i + 1) % 4) * 0.8;
337	      const x = (Math.sin(hAngle) * hRadius * MAX_HORIZONTAL_OFFSET) / 3;
338	      const y = (Math.cos(vAngle) * vRadius * MAX_VERTICAL_OFFSET) / 4;
339	      const z = (DEPTH_RANGE / VISIBLE_COUNT) * i;
340	      const imageIndex = i % count;
341	
342	      const geo = new THREE.PlaneGeometry(1, 1, 32, 32);
343	      this._geometries.push(geo);
344	
345	      const mat = new THREE.ShaderMaterial({
346	        transparent: true,
347	        uniforms: {
348	          map: { value: textures[imageIndex] ?? null },
349	          opacity: { value: 0.0 },
350	          blurAmount: { value: 0.0 },
351	          scrollForce: { value: 0.0 },
352	          time: { value: 0.0 },
353	          isHovered: { value: 0.0 },
354	        },
355	        vertexShader: VERTEX_SHADER,
356	        fragmentShader: FRAGMENT_SHADER,
357	      });
358	      this._materials.push(mat);
359	
360	      const mesh = new THREE.Mesh(geo, mat);
361	      mesh.position.set(x, y, z - HALF_RANGE);
362	      this._applyTextureScale(mesh, textures[imageIndex] ?? null);
363	
364	      scene.add(mesh);
365	      this._planes.push({ mesh, data: { index: i, z, imageIndex, x, y } });
366	      this._meshList.push(mesh);
367	    }
368	  }
369	
370	  private _applyTextureScale(
371	    mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>,
372	    tex: THREE.Texture | null,
373	  ): void {
374	    const img = tex?.image as { width?: number; height?: number } | undefined;
375	    if (img?.width && img.height) {
376	      const aspect: number = img.width / img.height;
377	      mesh.scale.set(aspect > 1 ? 2 * aspect : 2, aspect > 1 ? 2 : 2 / aspect, 1);
378	    } else {
379	      mesh.scale.set(2, 2, 1);
380	    }
381	  }
382	
383	  private readonly _tick = (): void => {
384	    if (this._disposed || !this._rendering) return;
385	    this._rafId = requestAnimationFrame(this._tick);
386	
387	    const clock = this._clock!;
388	    const renderer = this._renderer!;
389	    const scene = this._scene!;
390	    const camera = this._camera!;
391	    const count = GALLERY_IMAGES.length;
392	
393	    const delta = Math.min(clock.getDelta(), MAX_DELTA);
394	    const elapsedTime = clock.elapsedTime;
395	
396	    // Frame-rate-independent exponential damping
397	    this._scrollVelocity *= Math.pow(SCROLL_DAMPING, delta * 60);
398	    if (Math.abs(this._scrollVelocity) < 0.0001) this._scrollVelocity = 0;
399	
400	    if (this._isAutoPlaying) {
401	      this._scrollVelocity += AUTO_PLAY_ACCEL * delta;
402	      if (this._scrollVelocity > MAX_SCROLL_VEL) this._scrollVelocity = MAX_SCROLL_VEL;
403	    }
404	
405	    const scrollForceUniform = Math.min(Math.abs(this._scrollVelocity) * 0.1, 1);
406	
407	    for (const record of this._planes) {
408	      const { mesh, data } = record;
409	      const mat = mesh.material;
410	
411	      data.z += this._scrollVelocity * delta * 10;
412	
413	      if (data.z >= DEPTH_RANGE) {
414	        data.z -= DEPTH_RANGE;
415	        data.imageIndex = (data.imageIndex + 1) % count;
416	        mat.uniforms["map"].value = this._textures[data.imageIndex] ?? null;
417	        this._applyTextureScale(mesh, this._textures[data.imageIndex] ?? null);
418	      } else if (data.z < 0) {
419	        data.z += DEPTH_RANGE;
420	        data.imageIndex = ((data.imageIndex - 1) % count + count) % count;
421	        mat.uniforms["map"].value = this._textures[data.imageIndex] ?? null;
422	        this._applyTextureScale(mesh, this._textures[data.imageIndex] ?? null);
423	      }
424	
425	      mesh.position.z = data.z - HALF_RANGE;
426	
427	      const n = data.z / DEPTH_RANGE;
428	      mat.uniforms["opacity"].value = computeOpacity(n);
429	      mat.uniforms["blurAmount"].value = computeBlur(n);
430	      mat.uniforms["scrollForce"].value = scrollForceUniform;
431	      mat.uniforms["time"].value = elapsedTime;
432	      mat.uniforms["isHovered"].value = data.index === this._hoveredIndex ? 1.0 : 0.0;
433	    }
434	
435	    renderer.render(scene, camera);
436	  };
437	
438	  private _startRaf(): void {
439	    if (this._rafId !== null || this._disposed) return;
440	    this._rendering = true;
441	    this._rafId = requestAnimationFrame(this._tick);
442	  }
443	
444	  private _stopRaf(): void {
445	    this._rendering = false;
446	    if (this._rafId !== null) {
447	      cancelAnimationFrame(this._rafId);
448	      this._rafId = null;
449	    }
450	  }
451	
452	  private _recordInteraction(): void {
453	    this._lastInteractionMs = performance.now();
454	    this._isAutoPlaying = false;
455	  }
456	
457	  private _tickAutoPlay(): void {
458	    if (this._disposed) {
459	      if (this._autoPlayIntervalId !== null) {
460	        clearInterval(this._autoPlayIntervalId);
461	        this._autoPlayIntervalId = null;
462	      }
463	      return;
464	    }
465	    this._isAutoPlaying = performance.now() - this._lastInteractionMs > IDLE_THRESHOLD_MS;
466	  }
467	
468	  private _syncSize(): void {
469	    const canvas = this._canvas;
470	    const renderer = this._renderer;
471	    const camera = this._camera;
472	    if (!canvas || !renderer || !camera) return;
473	    const w = canvas.clientWidth;
474	    const h = canvas.clientHeight;
475	    if (w <= 0 || h <= 0) return;
476	    renderer.setSize(w, h, false);
477	    camera.aspect = w / h;
478	    camera.updateProjectionMatrix();
479	  }
480	
481	  private _observeResize(): void {
482	    if (!this._canvas) return;
483	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
484	    this._resizeObserver.observe(this._canvas);
485	  }
486	
487	  private _observeVisibility(): void {
488	    if (!this._canvas) return;
489	    this._intersectionObserver = new IntersectionObserver(
490	      (entries) => {
491	        if (entries[0]?.isIntersecting) {
492	          this._startRaf();
493	        } else {
494	          this._stopRaf();
495	        }
496	      },
497	      { threshold: 0 },
498	    );
499	    this._intersectionObserver.observe(this._canvas);
500	  }
501	
502	  private _attachInputListeners(): void {
503	    const canvas = this._canvas!;
504	    canvas.addEventListener("wheel", this._onWheel, { passive: false });
505	    canvas.addEventListener("touchstart", this._onTouchStart, { passive: true });
506	    canvas.addEventListener("touchmove", this._onTouchMove, { passive: false });
507	    canvas.addEventListener("pointermove", this._onPointerMove);
508	    canvas.addEventListener("pointerleave", this._onPointerLeave);
509	    window.addEventListener("keydown", this._onKeyDown);
510	  }
511	
512	  private _detachInputListeners(): void {
513	    const canvas = this._canvas!;
514	    canvas.removeEventListener("wheel", this._onWheel);
515	    canvas.removeEventListener("touchstart", this._onTouchStart);
516	    canvas.removeEventListener("touchmove", this._onTouchMove);
517	    canvas.removeEventListener("pointermove", this._onPointerMove);
518	    canvas.removeEventListener("pointerleave", this._onPointerLeave);
519	    window.removeEventListener("keydown", this._onKeyDown);
520	  }
521	}
